CREATE TABLE dbo.AspNetUsers (Id nvarchar(450) NOT NULL PRIMARY KEY, UserName nvarchar(256) NULL, NormalizedUserName nvarchar(256) NULL, Email nvarchar(256) NULL, NormalizedEmail nvarchar(256) NULL, EmailConfirmed bit NOT NULL DEFAULT 0, PasswordHash nvarchar(max) NULL, SecurityStamp nvarchar(max) NULL, ConcurrencyStamp nvarchar(max) NULL, PhoneNumber nvarchar(max) NULL, PhoneNumberConfirmed bit NOT NULL DEFAULT 0, TwoFactorEnabled bit NOT NULL DEFAULT 0, LockoutEnd datetimeoffset NULL, LockoutEnabled bit NOT NULL DEFAULT 0, AccessFailedCount int NOT NULL DEFAULT 0, DisplayName nvarchar(160) NULL);
CREATE UNIQUE INDEX IX_AspNetUsers_NormalizedUserName ON dbo.AspNetUsers(NormalizedUserName) WHERE NormalizedUserName IS NOT NULL;
CREATE INDEX IX_AspNetUsers_NormalizedEmail ON dbo.AspNetUsers(NormalizedEmail);
CREATE TABLE dbo.AspNetRoles (Id nvarchar(450) NOT NULL PRIMARY KEY, Name nvarchar(256) NULL, NormalizedName nvarchar(256) NULL, ConcurrencyStamp nvarchar(max) NULL);
CREATE UNIQUE INDEX IX_AspNetRoles_NormalizedName ON dbo.AspNetRoles(NormalizedName) WHERE NormalizedName IS NOT NULL;
CREATE TABLE dbo.AspNetUserRoles (UserId nvarchar(450) NOT NULL REFERENCES dbo.AspNetUsers ON DELETE CASCADE, RoleId nvarchar(450) NOT NULL REFERENCES dbo.AspNetRoles ON DELETE CASCADE, PRIMARY KEY(UserId, RoleId));
CREATE TABLE dbo.AspNetUserClaims (Id int IDENTITY PRIMARY KEY, UserId nvarchar(450) NOT NULL REFERENCES dbo.AspNetUsers ON DELETE CASCADE, ClaimType nvarchar(max) NULL, ClaimValue nvarchar(max) NULL);
CREATE TABLE dbo.AspNetRoleClaims (Id int IDENTITY PRIMARY KEY, RoleId nvarchar(450) NOT NULL REFERENCES dbo.AspNetRoles ON DELETE CASCADE, ClaimType nvarchar(max) NULL, ClaimValue nvarchar(max) NULL);
CREATE TABLE dbo.AspNetUserLogins (LoginProvider nvarchar(450) NOT NULL, ProviderKey nvarchar(450) NOT NULL, ProviderDisplayName nvarchar(max) NULL, UserId nvarchar(450) NOT NULL REFERENCES dbo.AspNetUsers ON DELETE CASCADE, PRIMARY KEY(LoginProvider, ProviderKey));
CREATE TABLE dbo.AspNetUserTokens (UserId nvarchar(450) NOT NULL REFERENCES dbo.AspNetUsers ON DELETE CASCADE, LoginProvider nvarchar(450) NOT NULL, Name nvarchar(450) NOT NULL, Value nvarchar(max) NULL, PRIMARY KEY(UserId, LoginProvider, Name));
CREATE TABLE dbo.Shops (ShopId int IDENTITY PRIMARY KEY, Name nvarchar(160) NOT NULL, Slug nvarchar(180) NOT NULL UNIQUE, Description nvarchar(1000) NULL, OwnerUserId nvarchar(450) NOT NULL REFERENCES dbo.AspNetUsers(Id), Status tinyint NOT NULL CONSTRAINT DF_Shops_Status DEFAULT 0, PlatformFeePercent decimal(5,2) NOT NULL CONSTRAINT DF_Shops_Fee DEFAULT 0, CreatedAt datetime2 NOT NULL CONSTRAINT DF_Shops_Created DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_Shops_Fee CHECK (PlatformFeePercent BETWEEN 0 AND 100));
CREATE TABLE dbo.ShopMemberships (ShopMembershipId bigint IDENTITY PRIMARY KEY, ShopId int NOT NULL REFERENCES dbo.Shops, UserId nvarchar(450) NOT NULL REFERENCES dbo.AspNetUsers(Id), RoleName nvarchar(40) NOT NULL, IsActive bit NOT NULL DEFAULT 1, UNIQUE(ShopId, UserId));
CREATE TABLE dbo.ShopBranches (ShopBranchId int IDENTITY PRIMARY KEY, ShopId int NOT NULL REFERENCES dbo.Shops, Name nvarchar(120) NOT NULL, AddressLine nvarchar(250) NOT NULL, City nvarchar(100) NOT NULL, PostalCode nvarchar(20) NOT NULL, Latitude decimal(9,6) NULL, Longitude decimal(9,6) NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE dbo.DeliveryZones (DeliveryZoneId int IDENTITY PRIMARY KEY, ShopBranchId int NOT NULL REFERENCES dbo.ShopBranches, Name nvarchar(120) NOT NULL, PostalCode nvarchar(20) NOT NULL, DeliveryFee decimal(10,2) NOT NULL DEFAULT 0, MinimumOrder decimal(10,2) NOT NULL DEFAULT 0, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE dbo.DeliverySlots (DeliverySlotId int IDENTITY PRIMARY KEY, ShopBranchId int NOT NULL REFERENCES dbo.ShopBranches, StartsAt time NOT NULL, EndsAt time NOT NULL, Capacity int NOT NULL, IsActive bit NOT NULL DEFAULT 1, CONSTRAINT CK_DeliverySlots_Time CHECK (EndsAt > StartsAt), CONSTRAINT CK_DeliverySlots_Capacity CHECK (Capacity > 0));
CREATE TABLE dbo.Categories (CategoryId int IDENTITY PRIMARY KEY, ParentCategoryId int NULL REFERENCES dbo.Categories, Name nvarchar(100) NOT NULL, Slug nvarchar(120) NOT NULL UNIQUE, IsActive bit NOT NULL DEFAULT 1, SortOrder int NOT NULL DEFAULT 0);
CREATE TABLE dbo.Products (ProductId int IDENTITY PRIMARY KEY, ShopId int NOT NULL REFERENCES dbo.Shops, CategoryId int NOT NULL REFERENCES dbo.Categories, Name nvarchar(180) NOT NULL, Description nvarchar(2000) NULL, IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.ProductVariants (ProductVariantId int IDENTITY PRIMARY KEY, ProductId int NOT NULL REFERENCES dbo.Products, SKU nvarchar(80) NOT NULL UNIQUE, UnitName nvarchar(40) NOT NULL, UnitQuantity decimal(10,3) NOT NULL, UnitPrice decimal(10,2) NOT NULL, CurrencyCode char(3) NOT NULL DEFAULT 'INR', IsDefault bit NOT NULL DEFAULT 0, IsActive bit NOT NULL DEFAULT 1, CONSTRAINT CK_ProductVariants_Price CHECK (UnitPrice >= 0), CONSTRAINT CK_ProductVariants_Quantity CHECK (UnitQuantity > 0));
CREATE TABLE dbo.ProductImages (ProductImageId bigint IDENTITY PRIMARY KEY, ProductId int NOT NULL REFERENCES dbo.Products, ImageUrl nvarchar(2048) NOT NULL, AltText nvarchar(250) NULL, SortOrder int NOT NULL DEFAULT 0);
CREATE TABLE dbo.Inventory (InventoryId bigint IDENTITY PRIMARY KEY, ShopBranchId int NOT NULL REFERENCES dbo.ShopBranches, ProductVariantId int NOT NULL REFERENCES dbo.ProductVariants, QuantityOnHand decimal(12,3) NOT NULL DEFAULT 0, ReorderLevel decimal(12,3) NOT NULL DEFAULT 0, UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(ShopBranchId, ProductVariantId), CHECK (QuantityOnHand >= 0));
CREATE TABLE dbo.StockMovements (StockMovementId bigint IDENTITY PRIMARY KEY, InventoryId bigint NOT NULL REFERENCES dbo.Inventory, QuantityChange decimal(12,3) NOT NULL, Reason nvarchar(40) NOT NULL, Notes nvarchar(500) NULL, ChangedByUserId nvarchar(450) NOT NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.ProductPriceHistory (ProductPriceHistoryId bigint IDENTITY PRIMARY KEY, ProductVariantId int NOT NULL REFERENCES dbo.ProductVariants, OldPrice decimal(10,2) NULL, NewPrice decimal(10,2) NOT NULL, ChangedByUserId nvarchar(450) NOT NULL, ChangedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Addresses (AddressId bigint IDENTITY PRIMARY KEY, UserId nvarchar(450) NOT NULL, Label nvarchar(60) NOT NULL, RecipientName nvarchar(160) NOT NULL, Phone nvarchar(30) NOT NULL, AddressLine nvarchar(300) NOT NULL, City nvarchar(100) NOT NULL, PostalCode nvarchar(20) NOT NULL, IsDefault bit NOT NULL DEFAULT 0);
CREATE TABLE dbo.Carts (CartId bigint IDENTITY PRIMARY KEY, UserId nvarchar(450) NOT NULL UNIQUE, UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.CartItems (CartItemId bigint IDENTITY PRIMARY KEY, CartId bigint NOT NULL REFERENCES dbo.Carts, ProductVariantId int NOT NULL REFERENCES dbo.ProductVariants, Quantity decimal(10,3) NOT NULL, UNIQUE(CartId, ProductVariantId), CHECK(Quantity > 0));
CREATE TABLE dbo.Wishlists (WishlistId bigint IDENTITY PRIMARY KEY, UserId nvarchar(450) NOT NULL, Name nvarchar(100) NOT NULL DEFAULT 'Favorites', UNIQUE(UserId, Name));
CREATE TABLE dbo.WishlistItems (WishlistItemId bigint IDENTITY PRIMARY KEY, WishlistId bigint NOT NULL REFERENCES dbo.Wishlists, ProductId int NOT NULL REFERENCES dbo.Products, AddedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(WishlistId, ProductId));
CREATE TABLE dbo.Orders (OrderId bigint IDENTITY PRIMARY KEY, OrderNumber nvarchar(32) NOT NULL UNIQUE, UserId nvarchar(450) NOT NULL, AddressId bigint NULL REFERENCES dbo.Addresses, OrderStatus tinyint NOT NULL DEFAULT 0, PaymentStatus tinyint NOT NULL DEFAULT 0, Subtotal decimal(12,2) NOT NULL, DeliveryFee decimal(12,2) NOT NULL DEFAULT 0, DiscountAmount decimal(12,2) NOT NULL DEFAULT 0, GrandTotal decimal(12,2) NOT NULL, CurrencyCode char(3) NOT NULL DEFAULT 'INR', CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CHECK(GrandTotal >= 0));
CREATE TABLE dbo.ShopOrders (ShopOrderId bigint IDENTITY PRIMARY KEY, OrderId bigint NOT NULL REFERENCES dbo.Orders, ShopId int NOT NULL REFERENCES dbo.Shops, ShopBranchId int NOT NULL REFERENCES dbo.ShopBranches, DeliverySlotId int NULL REFERENCES dbo.DeliverySlots, Status tinyint NOT NULL DEFAULT 0, DeliveryFee decimal(10,2) NOT NULL DEFAULT 0, UNIQUE(OrderId, ShopId));
CREATE TABLE dbo.OrderItems (OrderItemId bigint IDENTITY PRIMARY KEY, ShopOrderId bigint NOT NULL REFERENCES dbo.ShopOrders, ProductVariantId int NULL REFERENCES dbo.ProductVariants, ProductName nvarchar(180) NOT NULL, UnitName nvarchar(40) NOT NULL, Quantity decimal(10,3) NOT NULL, UnitPrice decimal(10,2) NOT NULL, LineTotal decimal(12,2) NOT NULL, CHECK(Quantity > 0));
CREATE TABLE dbo.OrderStatusHistory (OrderStatusHistoryId bigint IDENTITY PRIMARY KEY, OrderId bigint NOT NULL REFERENCES dbo.Orders, ShopOrderId bigint NULL REFERENCES dbo.ShopOrders, Status tinyint NOT NULL, Note nvarchar(500) NULL, ChangedByUserId nvarchar(450) NOT NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Payments (PaymentId bigint IDENTITY PRIMARY KEY, OrderId bigint NOT NULL REFERENCES dbo.Orders, Method tinyint NOT NULL, Status tinyint NOT NULL DEFAULT 0, Amount decimal(12,2) NOT NULL, GatewayReference nvarchar(200) NULL, PaidAt datetime2 NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Refunds (RefundId bigint IDENTITY PRIMARY KEY, PaymentId bigint NOT NULL REFERENCES dbo.Payments, Amount decimal(12,2) NOT NULL, Reason nvarchar(500) NOT NULL, Status tinyint NOT NULL DEFAULT 0, GatewayReference nvarchar(200) NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Coupons (CouponId int IDENTITY PRIMARY KEY, ShopId int NULL REFERENCES dbo.Shops, Code nvarchar(40) NOT NULL UNIQUE, DiscountType tinyint NOT NULL, DiscountValue decimal(10,2) NOT NULL, MinimumOrder decimal(10,2) NOT NULL DEFAULT 0, StartsAt datetime2 NOT NULL, EndsAt datetime2 NOT NULL, UsageLimit int NULL, IsActive bit NOT NULL DEFAULT 1, CHECK(EndsAt > StartsAt));
CREATE TABLE dbo.CouponUsage (CouponUsageId bigint IDENTITY PRIMARY KEY, CouponId int NOT NULL REFERENCES dbo.Coupons, OrderId bigint NOT NULL REFERENCES dbo.Orders, UserId nvarchar(450) NOT NULL, DiscountAmount decimal(10,2) NOT NULL, UsedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(CouponId, OrderId));
CREATE TABLE dbo.Reviews (ReviewId bigint IDENTITY PRIMARY KEY, ProductId int NOT NULL REFERENCES dbo.Products, UserId nvarchar(450) NOT NULL, OrderItemId bigint NOT NULL REFERENCES dbo.OrderItems, Rating tinyint NOT NULL, Comment nvarchar(1000) NULL, IsPublished bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(UserId, OrderItemId), CHECK(Rating BETWEEN 1 AND 5));
CREATE TABLE dbo.Notifications (NotificationId bigint IDENTITY PRIMARY KEY, UserId nvarchar(450) NOT NULL, Title nvarchar(160) NOT NULL, Message nvarchar(1000) NOT NULL, ReadAt datetime2 NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.AuditLogs (AuditLogId bigint IDENTITY PRIMARY KEY, ActorUserId nvarchar(450) NOT NULL, Action nvarchar(120) NOT NULL, EntityName nvarchar(120) NOT NULL, EntityId nvarchar(100) NOT NULL, Details nvarchar(max) NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
GO
CREATE INDEX IX_Products_Shop_Category ON dbo.Products(ShopId, CategoryId, IsActive);
CREATE INDEX IX_Inventory_Variant_Availability ON dbo.Inventory(ProductVariantId, QuantityOnHand);
CREATE INDEX IX_Orders_User_Created ON dbo.Orders(UserId, CreatedAt DESC);
CREATE INDEX IX_ShopOrders_Shop_Status ON dbo.ShopOrders(ShopId, Status);
